{
  "avaliacoes": [
    {
      "id": "E1e78fa5fca7d9209",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Biofilmes de proteção e o surgimento de cepas resistentes são apontados como fatores que reduzem a efetividade do uso de biocidas no controle microbiológico.",
          "trechos": [
            "E1e78fa5fca7d9209:0:700",
            "E1e78fa5fca7d9209:700:1396"
          ],
          "condicoes": [
            "contexto de controle de BRS e biocorrosão em sistemas da indústria do petróleo"
          ],
          "limites": [
            "o trecho não quantifica perda de desempenho nem compara biocidas específicos",
            "a fonte apresenta revisão e objetivos de pesquisa, não comprovação operacional em FPSO"
          ]
        },
        {
          "proposicao": "A injeção de nitrato, isoladamente ou combinada com nitrito, molibdato e/ou biocidas, é apresentada como alternativa estudada para exclusão biocompetitiva e controle microbiológico.",
          "trechos": [
            "E1e78fa5fca7d9209:0:700"
          ],
          "condicoes": [
            "tratamento voltado a campos de petróleo com problemas associados a BRS"
          ],
          "limites": [
            "a eficiência do nitrato nem sempre é previsível",
            "o tratamento depende de custo, disponibilidade e modo de aplicação",
            "dependendo do sistema, pode ser necessária adição de outros sais e/ou biomassa exógena"
          ]
        },
        {
          "proposicao": "A dificuldade de eliminar BRS aderidas a estruturas metálicas na forma de biofilmes motiva a busca de estratégias alternativas, como o uso de micróbios antagonistas ou produtos de seu metabolismo.",
          "trechos": [
            "E1e78fa5fca7d9209:700:1396",
            "E1e78fa5fca7d9209:1396:2092"
          ],
          "condicoes": [
            "aplicação proposta para controle de biocorrosão e souring em ambientes com água produzida"
          ],
          "limites": [
            "o trecho descreve linha de pesquisa e potencial de aplicação, não resultado consolidado de campo",
            "não há critérios de seleção operacional nem compatibilidade com materiais detalhados"
          ]
        }
      ]
    },
    {
      "id": "Ef62a32775425801a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A formação de biofilme aumenta a resistência dos organismos sésseis a antimicrobianos, e uma abordagem citada para controlar crescimento bacteriano e biofilme é combinar agentes inibitórios de grande espectro com revestimento de superfície.",
          "trechos": [
            "Ef62a32775425801a:0:690"
          ],
          "condicoes": [
            "contexto de corrosão microbiologicamente influenciada"
          ],
          "limites": [
            "a fonte não informa desempenho comparativo nem materiais de revestimento específicos",
            "não há validação explícita para água do mar em FPSO"
          ]
        },
        {
          "proposicao": "Para controlar souring, o texto lista remoção de sulfato da água de injeção por membranas, exposição da água a irradiação/micro-ondas/ultrassom ou uso de biocidas, remoção físico-química de H2S e controle microbiológico com nitrato e molibdato.",
          "trechos": [
            "Ef62a32775425801a:690:1382",
            "Ef62a32775425801a:1382:2077"
          ],
          "condicoes": [
            "aplicação em sistemas afetados pela redução de sulfato por BRS"
          ],
          "limites": [
            "o trecho compila métodos possíveis sem estabelecer critério de seleção entre eles",
            "não apresenta dosagem, janelas operacionais ou compatibilidade química detalhada"
          ]
        },
        {
          "proposicao": "Biocidas são descritos como de alto custo, de eficiência curta e muitas vezes ineficazes quando há biofilmes; além disso, são apontados como tóxicos e de difícil degradação, com potencial de impacto ambiental se aplicados sem avaliação de risco.",
          "trechos": [
            "Ef62a32775425801a:1382:2077"
          ],
          "condicoes": [
            "especialmente quando biofilmes microbianos estão formados",
            "na ausência de devida avaliação do risco ambiental"
          ],
          "limites": [
            "o texto não distingue comportamento por biocida específico",
            "a menção a incentivo legislativo para substituição não define requisito brasileiro"
          ]
        }
      ]
    },
    {
      "id": "E105de9bedc85d319",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A água de injeção é usada para recuperar a produtividade de poços maduros, sendo preparada com água do mar ou água doce e com diversos produtos químicos, incluindo biocidas, inibidores de corrosão e de incrustação.",
          "trechos": [
            "E105de9bedc85d319:0:694",
            "E105de9bedc85d319:694:1388"
          ],
          "condicoes": [
            "contexto de recuperação por injeção de água pressurizada a partir da superfície"
          ],
          "limites": [
            "a fonte não estabelece formulações, dosagens ou sequência de tratamento",
            "não detalha compatibilidade entre esses químicos"
          ]
        },
        {
          "proposicao": "Os produtos químicos adicionados à água de injeção têm funções relacionadas à recuperação e bombeamento dos hidrocarbonetos e à proteção de estruturas metálicas contra processos corrosivos.",
          "trechos": [
            "E105de9bedc85d319:694:1388"
          ],
          "condicoes": [
            "uso de água de injeção preparada para sistemas de produção"
          ],
          "limites": [
            "o trecho não discrimina mecanismo individual de cada classe química",
            "não informa consequências de incompatibilidade com água de formação"
          ]
        },
        {
          "proposicao": "As características físico-químicas e microbiológicas da água de produção dependem de particularidades de cada poço, especialmente idade geológica e profundidade do reservatório.",
          "trechos": [
            "E105de9bedc85d319:1388:2081",
            "E105de9bedc85d319:2081:2403"
          ],
          "condicoes": [
            "variação entre poços e reservatórios"
          ],
          "limites": [
            "a fonte não fornece critérios diretos de compatibilidade entre água injetada e formação",
            "não há parâmetros operacionais específicos para monitoramento"
          ]
        }
      ]
    },
    {
      "id": "E4a70fca79b3d7198",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A aplicação de biocidas é apresentada como possibilidade de controle de populações microbianas em reservatórios, mas o próprio texto afirma que sua eficiência para controle de souring ainda não foi comprovada de forma clara.",
          "trechos": [
            "E4a70fca79b3d7198:0:692",
            "E4a70fca79b3d7198:692:1392"
          ],
          "condicoes": [
            "uso visando controle de souring em reservatório"
          ],
          "limites": [
            "experiências mencionadas no Mar do Norte são sugestivas, não conclusivas",
            "a ausência de souring em alguns campos tratados e não tratados impede inferência causal clara",
            "norma estrangeira ou prática regional não pode ser convertida em requisito geral"
          ]
        },
        {
          "proposicao": "Biocidas são descritos como compostos muito reativos, sujeitos a rápida inativação por características do reservatório como temperatura e pressão e por sua própria constituição, o que reduz a efetividade no controle de BRS naturais do interior da rocha-reservatório.",
          "trechos": [
            "E4a70fca79b3d7198:692:1392"
          ],
          "condicoes": [
            "aplicação em reservatórios com BRS naturais",
            "presença de condições de reservatório que favorecem inativação"
          ],
          "limites": [
            "não há quantificação da inativação",
            "não diferencia biocidas por base ativa"
          ]
        },
        {
          "proposicao": "Seqüestrantes de H2S e inibidores de corrosão, inclusive sais de nitrato e nitrito, são usados para combater problemas de souring e CIM, porém o texto ressalta que inibidores protegem o metal contra BRS e seus metabólitos sem eliminar a causa, exigindo tratamento contínuo e monitoramento constante.",
          "trechos": [
            "E4a70fca79b3d7198:1392:2089",
            "E4a70fca79b3d7198:2089:2340"
          ],
          "condicoes": [
            "uso industrial contínuo em tentativa de controle de souring e corrosão"
          ],
          "limites": [
            "a afirmação de extrema eficiência para proteção por nitrito e nitrato aparece sem detalhamento experimental no trecho",
            "o texto não informa limites de aplicação, compatibilidade com materiais ou custos numéricos"
          ]
        }
      ]
    },
    {
      "id": "Ed052826acf9a1208",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na recuperação secundária, a injeção de água ou gás mantém a pressão do reservatório; em campos offshore, o uso de água do mar é apresentado como prática amplamente aplicada pela disponibilidade e quantidade.",
          "trechos": [
            "Ed052826acf9a1208:0:694"
          ],
          "condicoes": [
            "contexto de recuperação secundária em grandes indústrias e campos offshore"
          ],
          "limites": [
            "o ganho percentual de recuperação está apagado",
            "o trecho não restringe a aplicação a um tipo específico de reservatório"
          ]
        },
        {
          "proposicao": "A água do mar pode favorecer a proliferação de BRS e outras bactérias em consórcio em sistemas de injeção, produção, linhas de transporte e no reservatório, associando-se a souring, CIM e plugueamento.",
          "trechos": [
            "Ed052826acf9a1208:694:1393"
          ],
          "condicoes": [
            "presença de características químicas e microbiológicas favoráveis ao crescimento microbiano"
          ],
          "limites": [
            "a fonte não detalha parâmetros de qualidade da água do mar que aumentam esse risco",
            "não há diferenciação entre mecanismos de incrustação e de plugueamento biológico"
          ]
        },
        {
          "proposicao": "A geração de H2S no fluido produzido pode elevar gastos com seqüestrantes e biocidas orgânicos, e o texto recomenda conhecer condições de crescimento bacteriano e ferramentas de monitoração e controle.",
          "trechos": [
            "Ed052826acf9a1208:1393:2087"
          ],
          "condicoes": [
            "cenário com H2S gerado no fluido produzido"
          ],
          "limites": [
            "é recomendação geral de capacitação e monitoramento, sem procedimento operacional detalhado",
            "não especifica instrumentos, frequências nem limites de controle"
          ]
        }
      ]
    },
    {
      "id": "Ea26d29c6776860b4",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A injeção de água do mar contendo sulfato torna o reservatório sujeito ao crescimento de BRS, que reduzem sulfato a sulfeto e podem causar prejuízos operacionais.",
          "trechos": [
            "Ea26d29c6776860b4:0:693"
          ],
          "condicoes": [
            "reservatórios submetidos à injeção de água do mar com sulfato"
          ],
          "limites": [
            "a concentração numérica de sulfato está apagada",
            "não define limiar a partir do qual o risco se torna crítico"
          ]
        },
        {
          "proposicao": "O aumento de H2S está associado à corrosão do aço e à contaminação do óleo armazenado, alterando a qualidade do produto; o texto também observa que H2S pode ter origem biológica ou química.",
          "trechos": [
            "Ea26d29c6776860b4:0:693",
            "Ea26d29c6776860b4:693:1385"
          ],
          "condicoes": [
            "sistemas aquosos e reservatórios contendo sulfetos metálicos nas rochas"
          ],
          "limites": [
            "a fonte usa a denominação souring de forma associada à CMI, o que pode simplificar fenômenos distintos",
            "não separa quantitativamente contribuição biológica e química"
          ]
        },
        {
          "proposicao": "A adição de biocidas é citada como forma de controle do souring, mas sua eficiência é limitada quando há biofilme, que geralmente protege as bactérias.",
          "trechos": [
            "Ea26d29c6776860b4:1385:2078"
          ],
          "condicoes": [
            "formação de biofilme bacteriano"
          ],
          "limites": [
            "não informa quais biocidas foram considerados",
            "não há critérios de dosagem, frequência de injeção ou compatibilidade com materiais"
          ]
        }
      ]
    }
  ],
